  1958	func sourceMaterializationDiffers(root, commit string, entries []ReviewBundleSubjectEntry) string {
  1959		if commit == "" || !hasGitMetadata(root) {
  1960			// No sealed commit, or no repository at all: nothing to compare with (a dispatch has both).
  1961			return ""
  1962		}
  1963		checkedDirs := map[string]bool{}
  1964		for _, entry := range entries {
  1965			if entry.Class == "submodule" {
  1966				continue
  1967			}
  1968			// The absence the bundle sealed is part of what it reviewed: a removed path, and the old
  1969			// side of a rename, must still be absent, whatever Git was told to ignore.
  1970			for _, gone := range removedSides(entry) {
  1971				if _, err := os.Lstat(filepath.Join(root, filepath.FromSlash(gone))); err == nil {
  1972					return gone + " (the bundle sealed it as removed, and it is there)"
  1973				}
  1974			}
  1975			if entry.Action == "removed" {
  1976				continue
  1977			}
  1978			rel := reviewBundleEntryPath(entry)
  1979			if linkAbove(root, rel, checkedDirs) {
  1980				return rel + " (a directory above it is a link, or not a directory)"
  1981			}
  1982			out, err := gitCommand("-C", root, "ls-tree", "-z", commit, "--", rel).Output()
  1983			if err != nil {
  1984				return rel + " (its record in the sealed commit could not be read: " + err.Error() + ")"
  1985			}
  1986			meta, _, ok := strings.Cut(strings.TrimSuffix(string(out), "\x00"), "\t")
  1987			fields := strings.Fields(meta)
  1988			if !ok || len(fields) < 3 {
  1989				continue // not in the sealed commit
  1990			}
  1991			mode, object := fields[0], fields[2]
  1992			info, lerr := os.Lstat(filepath.Join(root, filepath.FromSlash(rel)))
  1993			if lerr != nil {
  1994				return rel + " (it cannot be inspected: " + lerr.Error() + ")"
  1995			}
  1996			switch mode {
  1997			case "120000":
  1998				target, rerr := os.Readlink(filepath.Join(root, filepath.FromSlash(rel)))
  1999				if info.Mode()&os.ModeSymlink == 0 || rerr != nil || gitBlobID("sha1", []byte(target)) != object && gitBlobID("sha256", []byte(target)) != object {
  2000					return rel + " (it is not the link the sealed commit records)"
  2001				}
  2002			default:
  2003				if !info.Mode().IsRegular() {
  2004					return rel + " (it is not a regular file, and the sealed commit records one)"
  2005				}
  2006				if runtime.GOOS != "windows" && (info.Mode().Perm()&0o111 != 0) != (mode == "100755") {
  2007					return rel + " (its executable bit differs)"
  2008				}
  2009			}
  2010		}
  2011		return ""
  2012	}

