201	func readShimProcStat(pid int) (shimProcStat, error) {
202		raw, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/stat")
203		if err != nil {
204			return shimProcStat{}, err
205		}
206		text := string(raw)
207		end := strings.LastIndexByte(text, ')')
208		if end < 0 {
209			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
210		}
211		f := strings.Fields(text[end+1:])
212		if len(f) < 2 {
213			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
214		}
215		ppid, err := strconv.Atoi(f[1])
216		if err != nil {
217			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
218		}
219		return shimProcStat{ppid: ppid, zombie: f[0] == "Z"}, nil
220	}
