222	// killPinnedChild signals pid through a pidfd while it is still a child of
223	// parent: a pid reused by an unrelated process is never signalled. It says
224	// whether the signal reached the process; one that already ended was not
225	// ended by the shim and is not reported (review round 11, N2).
226	func killPinnedChild(pid, parent int) (bool, error) {
227		fd, err := unix.PidfdOpen(pid, 0)
228		if errors.Is(err, unix.ESRCH) {
229			return false, nil
230		}
231		if err != nil {
232			return false, fmt.Errorf("process %d could not be pinned: %w", pid, err)
233		}
234		defer unix.Close(fd)
235		st, err := readShimProcStat(pid)
236		if reviewProcessGoneErr(err) || err == nil && (st.ppid != parent || st.zombie) {
237			return false, nil
238		}
239		if err != nil {
240			return false, fmt.Errorf("process %d could not be inspected: %w", pid, err)
241		}
242		if err := unix.PidfdSendSignal(fd, unix.SIGKILL, nil, 0); err != nil {
243			if errors.Is(err, unix.ESRCH) {
244				return false, nil
245			}
246			return false, fmt.Errorf("process %d could not be ended: %w", pid, err)
247		}
248		return true, nil
249	}
