   115	// reapShimSubtree ends and reaps every child of the shim, including the
   116	// orphans its subreaper status adopted, until none is left.
   117	func reapShimSubtree() ([]string, error) {
   118		self := os.Getpid()
   119		var ended []string
   120		seen := map[int]bool{}
   121		deadline := time.Now().Add(reviewReapWait)
   122		// A process that cannot be inspected or ended is not a reason to stop:
   123		// the others are still ended, and the problem is reported at the end
   124		// (review round 9, N3).
   125		var problems []string
   126		note := func(err error) {
   127			if len(problems) < 8 {
   128				problems = append(problems, err.Error())
   129			}
   130		}
   131		for {
   132			children := 0
   133			problems = problems[:0]
   134			// /proc is read in batches under the deadline, never materialized
   135			// whole (review round 13, N3).
   136			dirs, err := readProcBatched(deadline)
   137			if err != nil {
   138				note(err)
   139			}
   140			for _, d := range dirs {
   141				pid, err := strconv.Atoi(d.Name())
   142				if err != nil || pid == self {
   143					continue
   144				}
   145				st, err := readShimProcStat(pid)
   146				if reviewProcessGoneErr(err) {
   147					continue
   148				}
   149				if err != nil {
   150					// A process of another user is never the run's: with procfs
   151					// mounted hidepid it is visible and unreadable (review round 10,
   152					// N1). Only one of this user is an unknown that may be the run's.
   153					if owner, oerr := reviewProcessOwner(pid); reviewProcessGoneErr(oerr) || oerr == nil && owner != os.Getuid() {
   154						continue
   155					}
   156					children++
   157					note(fmt.Errorf("process %d could not be inspected: %w", pid, err))
   158					continue
   159				}
   160				if st.ppid != self {
   161					continue
   162				}
   163				children++
   164				if !st.zombie {
   165					// A pid is reported ended only once its signal was delivered
   166					// (review round 10, N3).
   167					if delivered, err := killPinnedChild(pid, self); err != nil {
   168						note(err)
   169					} else if delivered {
   170						seen[pid] = true
   171					}
   172				}
   173			}
   174			for {
   175				pid, err := unix.Wait4(-1, nil, unix.WNOHANG, nil)
   176				if pid <= 0 || err != nil {
   177					break
   178				}
   179				// A pid is reported ended once it was signalled and reaped
   180				// (review round 12, N2).
   181				if seen[pid] {
   182					delete(seen, pid)
   183					ended = append(ended, strconv.Itoa(pid))
   184				}
   185			}
   186			if children == 0 && len(problems) == 0 {
   187				return ended, nil
   188			}
   189			if time.Now().After(deadline) {
   190				return ended, fmt.Errorf("%d process(es) of the run could not be ended: %s", children, strings.Join(problems, "; "))
   191			}
   192			time.Sleep(20 * time.Millisecond)
   193		}
   194	}
