   277	// readDirBounded lists at most max entries of dir and says whether more exist.
   278	func readDirBounded(dir string, max int) ([]os.DirEntry, bool, error) {
   279		f, err := os.Open(dir)
   280		if err != nil {
   281			return nil, false, err
   282		}
   283		defer f.Close()
   284		entries, err := f.ReadDir(max + 1)
   285		if err != nil && !errors.Is(err, io.EOF) {
   286			return nil, false, err
   287		}
   288		if len(entries) > max {
   289			return entries[:max], true, nil
   290		}
   291		return entries, false, nil
   292	}
