  1791			return fmt.Errorf("the file is not named after the run it holds")
  1792		}
  1793		if run.LedgerVersion != 0 && run.LedgerVersion != 1 {
  1794			return fmt.Errorf("unknown ledger version %d", run.LedgerVersion)
  1795		}
  1796		if run.SchemaVersion != 1 {
  1797			return fmt.Errorf("schema_version %d is not read by this engine", run.SchemaVersion)
  1798		}
  1799		switch run.Status {
  1800		case ReviewRunCompleted, ReviewRunFailed, ReviewRunStale, ReviewRunInterrupted:
  1801		default:
  1802			return fmt.Errorf("status %q is not a state of a run", run.Status)
  1803		}
  1804		if err := validateContinuityRun(run); err != nil {
  1805			return err
  1806		}
  1807		if run.BundleID == "" || run.Scope == "" {
  1808			return fmt.Errorf("the bundle or scope is missing")
  1809		}
  1810		for _, at := range []string{run.StartedAt, run.EndedAt} {
  1811			if _, err := time.Parse(time.RFC3339Nano, at); err != nil {
  1812				return fmt.Errorf("an instant of the run is not RFC3339: %q", at)
  1813			}
