  1816			return fmt.Errorf("the transcript path is not the one the run is written with")
  1817		}
  1818		unsealed := run
  1819		unsealed.RunID, unsealed.TranscriptPath, unsealed.SupersededBy, unsealed.Path = "", "", "", ""
  1820		identity, _ := json.Marshal(unsealed)
  1821		sum := sha256.Sum256(identity)
  1822		if run.RunID != "rrn-"+hex.EncodeToString(sum[:])[:16] {
  1823			return fmt.Errorf("the identity of the run is not derived from its content")
  1824		}
  1825		return nil
  1826	}
