    19	// isolateProcessGroup starts the adapter in its own process group, and makes
    20	// the context's cancellation kill that whole group.
    21	func isolateProcessGroup(cmd *exec.Cmd) {
    22		cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
    23		cmd.Cancel = func() error {
    24			return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
    25		}
    26	}
